1	// Test-only fault-injection shim, preloaded into the messagetag process by
2	// the regression suite (tests/regression_test.py) to simulate a write(2)
3	// failure on standard output that happens *after* part of the result line
4	// has already been accepted. A closed real pipe can deliver EPIPE but not
5	// a controlled partial-then-fail sequence (the 65-byte result fits in the
6	// pipe buffer as one write), and exercising ENOSPC would otherwise require
7	// a genuinely full filesystem. Overriding write() makes "N bytes accepted,
8	// then the next write fails with a chosen errno" deterministic.
9	//
10	// Behaviour is controlled through environment variables:
11	//   MESSAGETAG_WRITE_FAULT_FD     fd to fault on (default 1 = stdout)
12	//   MESSAGETAG_WRITE_FAULT_AFTER  number of bytes to deliver to that fd
13	//                                 before writes start failing
14	//   MESSAGETAG_WRITE_FAULT_ERRNO  errno for the failure (default EPIPE,
15	//                                 e.g. 28 for ENOSPC, 5 for EIO)
16	//
17	// Only writes to the chosen fd are affected: the failure diagnostic that
18	// messagetag subsequently writes to stderr (fd 2) passes through untouched,
19	// so the test can still observe it. Every other fd is written normally.
20	// Bytes up to the allowed total are delivered through the real write()
21	// (shortened as needed so the boundary lands mid-write); the next write
22	// returns -1 with the configured errno and keeps doing so.
23	//
24	// This is Linux-specific in spirit but only relies on POSIX write(2) and
25	// dlsym; it builds on any platform the suite builds the read shim on.
26	
27	#if defined(__linux__)
28	
29	#define _GNU_SOURCE
30	#include <dlfcn.h>
31	#include <errno.h>
32	#include <stdlib.h>
33	#include <unistd.h>
34	
35	namespace {
36	
37	using WriteFn = ssize_t (*)(int, const void*, size_t);
38	
39	WriteFn realWrite = nullptr;
40	int targetFd = 1;
41	long failAfter = -1;   // -1 => shim inert (no fault configured)
42	int faultErrno = EPIPE;
43	long delivered = 0;
44	
45	void init() {
46	    if (realWrite != nullptr) {
47	        return;
48	    }
49	    realWrite = reinterpret_cast<WriteFn>(dlsym(RTLD_NEXT, "write"));
50	    const char* fdEnv = getenv("MESSAGETAG_WRITE_FAULT_FD");
51	    if (fdEnv != nullptr && fdEnv[0] != '\0') {
52	        targetFd = atoi(fdEnv);
53	    }
54	    const char* after = getenv("MESSAGETAG_WRITE_FAULT_AFTER");
55	    if (after != nullptr) {
56	        failAfter = atol(after);
57	    }
58	    const char* err = getenv("MESSAGETAG_WRITE_FAULT_ERRNO");
59	    if (err != nullptr && err[0] != '\0') {
60	        faultErrno = atoi(err);
61	    }
62	}
63	
64	}  // namespace
65	
66	extern "C" ssize_t write(int fd, const void* buf, size_t count) {
67	    init();
68	    if (realWrite == nullptr) {
69	        errno = ENOSYS;
70	        return -1;
71	    }
72	    if (failAfter >= 0 && fd == targetFd) {
73	        if (delivered >= failAfter) {
74	            errno = faultErrno;
75	            return -1;
76	        }
77	        // Deliver no more than the remaining allowed prefix in this call;
78	        // the next write then fails. A short write(2) result is ordinary
79	        // and the caller is expected to continue with the rest.
80	        long remaining = failAfter - delivered;
81	        if (static_cast<long>(count) > remaining) {
82	            count = static_cast<size_t>(remaining);
83	        }
84	        ssize_t got = realWrite(fd, buf, count);
85	        if (got > 0) {
86	            delivered += got;
87	        }
88	        return got;
89	    }
90	    return realWrite(fd, buf, count);
91	}
92	
93	#else  // !defined(__linux__)
94	
95	// Empty translation unit off Linux, mirroring read_fault_shim.cpp.
96	
97	#endif
