1	// Test-only fault-injection shim, preloaded into the messagetag process by
2	// the regression suite (tests/regression_test.py) to simulate a read(2)
3	// failure that happens *after* part of the message file has already been
4	// read successfully. Neither a missing file nor an unreadable-permission
5	// file can produce that situation: both fail at open time. Overriding
6	// read() is what lets the tests reach the "open succeeded, some bytes
7	// delivered, then the read fails" path deterministically, without relying
8	// on the account's permissions or on special filesystems.
9	//
10	// Behaviour is controlled through environment variables:
11	//   MESSAGETAG_READ_FAULT_PATH   absolute path of the file to fault on;
12	//                                every other file is read normally
13	//   MESSAGETAG_READ_FAULT_AFTER  number of bytes to deliver before the
14	//                                first failing read (must be > 0 so a
15	//                                non-empty prefix has already been read)
16	//   MESSAGETAG_READ_FAULT_ERRNO  optional errno for the failure
17	//                                (default EIO)
18	//
19	// The failing read returns -1 once the allowed prefix has been delivered;
20	// every subsequent read of that file fails the same way.
21	//
22	// This is Linux-specific (it identifies the target file through
23	// /proc/self/fd); on other platforms it compiles to a pass-through and the
24	// regression suite skips the fault-injection test.
25	
26	#if defined(__linux__)
27	
28	#define _GNU_SOURCE
29	#include <dlfcn.h>
30	#include <errno.h>
31	#include <stdio.h>
32	#include <stdlib.h>
33	#include <string.h>
34	#include <unistd.h>
35	
36	namespace {
37	
38	using ReadFn = ssize_t (*)(int, void*, size_t);
39	
40	ReadFn realRead = nullptr;
41	const char* targetPath = nullptr;
42	long failAfter = 0;
43	int faultErrno = EIO;
44	long delivered = 0;
45	
46	void init() {
47	    if (realRead != nullptr) {
48	        return;
49	    }
50	    realRead = reinterpret_cast<ReadFn>(dlsym(RTLD_NEXT, "read"));
51	    targetPath = getenv("MESSAGETAG_READ_FAULT_PATH");
52	    const char* after = getenv("MESSAGETAG_READ_FAULT_AFTER");
53	    failAfter = (after != nullptr) ? atol(after) : 0;
54	    const char* err = getenv("MESSAGETAG_READ_FAULT_ERRNO");
55	    if (err != nullptr) {
56	        faultErrno = atoi(err);
57	    }
58	}
59	
60	// Does fd refer to the file the fault is configured for? Resolved through
61	// /proc/self/fd so library/loader reads of unrelated files are untouched.
62	bool isTarget(int fd) {
63	    if (targetPath == nullptr || targetPath[0] == '\0') {
64	        return false;
65	    }
66	    char link[64];
67	    snprintf(link, sizeof(link), "/proc/self/fd/%d", fd);
68	    char path[4096];
69	    ssize_t len = readlink(link, path, sizeof(path) - 1);
70	    if (len <= 0) {
71	        return false;
72	    }
73	    path[len] = '\0';
74	    return strcmp(path, targetPath) == 0;
75	}
76	
77	}  // namespace
78	
79	extern "C" ssize_t read(int fd, void* buf, size_t count) {
80	    init();
81	    if (realRead == nullptr) {
82	        errno = ENOSYS;
83	        return -1;
84	    }
85	    if (failAfter > 0 && isTarget(fd)) {
86	        if (delivered >= failAfter) {
87	            errno = faultErrno;
88	            return -1;
89	        }
90	        // Shorten the read so no more than the allowed prefix is delivered;
91	        // a short read(2) result is normal and the caller will retry, at
92	        // which point the branch above reports the failure.
93	        if (count > static_cast<size_t>(failAfter - delivered)) {
94	            count = static_cast<size_t>(failAfter - delivered);
95	        }
96	        ssize_t got = realRead(fd, buf, count);
97	        if (got > 0) {
98	            delivered += got;
99	        }
100	        return got;
101	    }
102	    return realRead(fd, buf, count);
103	}
104	
105	#else  // !defined(__linux__)
106	
107	// Empty translation unit off Linux: the shim exports nothing, and the
108	// regression suite only runs the fault-injection test where /proc/self/fd
109	// exists, so the unused library is harmless.
110	
111	#endif
