    }
    const char* after = getenv("MESSAGETAG_WRITE_FAULT_AFTER");
    if (after != nullptr) {
        failAfter = atol(after);
    }
    const char* err = getenv("MESSAGETAG_WRITE_FAULT_ERRNO");
