                if (event.value > 0 &&
                    static_cast<long>(count) > event.value) {
                    count = static_cast<size_t>(event.value);
                }
                return realWrite(fd, buf, count);
            case kEventPass:
                return realWrite(fd, buf, count);
        }
    }
    if (failAfter >= 0) {
        if (delivered >= failAfter) {
            errno = faultErrno;
            return -1;
        }
